param([string]$BaselineDirectory='',[string]$OutputDirectory='',[ValidateRange(3,15)][int]$Runs=5,[ValidateRange(1,1000000)][int]$Iterations=1000,[ValidateRange(1,10000)][int]$Warmup=64,[ValidateSet('iso','ms')][string]$Mode='iso',[ValidateRange(30,2000)][int]$MinimumSampleMilliseconds=50)
$ErrorActionPreference='Stop'
