function Write-CoalesceBenchmarkStatus([string]$State,[string]$Failure='', [string]$EvidenceHash=''){
    [ordered]@{schema_version=1;version=$script:Version;source_tree_sha256=$script:SourceFingerprint;status=$State;updated_utc=[DateTime]::UtcNow.ToString('o');error=$(if($Failure){$Failure}else{$null});evidence=(Join-Path (Split-Path $script:CoalesceBenchmarkStatus) 'evidence.json');evidence_sha256=$(if($EvidenceHash){$EvidenceHash}else{$null})}|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $script:CoalesceBenchmarkStatus -Encoding utf8
}
trap{$failure=$_;if($script:CoalesceBenchmarkStatus){Write-CoalesceBenchmarkStatus -State 'failed' -Failure $failure.Exception.Message};throw $failure}

. (Join-Path $PSScriptRoot '../build/common.ps1')
$script:SourceFingerprint=Get-SourceFingerprint;$utf8=[Text.UTF8Encoding]::new($false)
$directory=if($OutputDirectory){if([IO.Path]::IsPathFullyQualified($OutputDirectory)){[IO.Path]::GetFullPath($OutputDirectory)}else{[IO.Path]::GetFullPath((Join-Path $script:RepoRoot $OutputDirectory))}}else{Join-Path $script:RepoRoot "out/coalesce-prefilter32-bench/$($script:SourceFingerprint.Substring(0,12))"}
New-Item -ItemType Directory -Path $directory -Force|Out-Null
$script:CoalesceBenchmarkStatus=Join-Path $directory 'run-status.json';Write-CoalesceBenchmarkStatus -State 'running'
if($script:Version-cne'2.0.0'){throw 'Coalesce benchmark version must remain2.0.0'}
Initialize-BuildEnvironment
$historical=-not[string]::IsNullOrWhiteSpace($BaselineDirectory);$accepted='1695a4be1d9b2ea619261b1d8ee6ee7f2372bb0b845884cb8d65f100c243bc18';$before=$null
if($historical){
 $before=(Resolve-Path -LiteralPath $BaselineDirectory).Path;$manifest=Get-Content -LiteralPath (Join-Path $before 'baseline.json') -Raw|ConvertFrom-Json
 [string[]]$paths=@($manifest.source_paths);[string[]]$ordered=$paths.Clone();[Array]::Sort($ordered,[StringComparer]::Ordinal)
 if($manifest.version-cne'2.0.0'-or$manifest.source_tree_sha256-cne$accepted-or$manifest.source_fingerprint_order-cne'typed string[] Ordinal'-or$paths.Count-ne743-or@($manifest.files.PSObject.Properties).Count-ne743-or($paths-join"`n")-cne($ordered-join"`n")){throw 'Unexpected coalesce benchmark baseline'}
 $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$identity=@()
 foreach($path in $paths){if(!$seen.Add($path)){throw 'Duplicate coalesce benchmark baseline path'};$hash=(Get-FileHash -LiteralPath (Join-Path $before $path)).Hash.ToLowerInvariant();if($hash-cne$manifest.files.$path){throw "Coalesce benchmark baseline raw hash differs:$path"};$identity+=$path+':'+$hash}
 foreach($path in $manifest.files.PSObject.Properties.Name){if(!$seen.Contains($path)){throw 'Coalesce benchmark baseline set differs'}}
 if([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes(($identity-join"`n")))).ToLowerInvariant()-cne$accepted){throw 'Coalesce benchmark baseline fingerprint differs'}
 if((Get-FileHash -LiteralPath (Join-Path $before 'driver/v2/session_coalesce.h')).Hash.ToLowerInvariant()-cne'5e4f762a8dfa3c1968b699b3e7249efda6a8355050bf77a3356b2d347e0cb426'){throw 'Unexpected prefilter before header'}
}
$closure=@(rg --files driver common include);if($LASTEXITCODE){throw 'Cannot enumerate coalesce benchmark closure'}
$closure+=@('tests/safety/guard_memory.h','wintun.props');$closure=@($closure|ForEach-Object {$_.Replace('\','/')}|Select-Object -Unique);$snapshot=Join-Path $directory 'current-source';$dependencies=@()
foreach($path in $closure){$current=Join-Path $script:RepoRoot $path;$hash=(Get-FileHash -LiteralPath $current).Hash.ToLowerInvariant();$copy=Join-Path $snapshot $path;New-Item -ItemType Directory -Path (Split-Path $copy) -Force|Out-Null;[IO.File]::WriteAllBytes($copy,[IO.File]::ReadAllBytes($current));if($historical-and$path-cne'driver/v2/session_coalesce.h'-and(Get-FileHash -LiteralPath (Join-Path $before $path)).Hash.ToLowerInvariant()-cne$hash){throw "Coalesce benchmark unrelated production changed:$path"};$dependencies+=@{path=$path;sha256=$hash;snapshot=$copy}}
$test=Join-Path $script:RepoRoot 'tests/bench/coalesce_prefilter32_bench.c';$builds=@()
foreach($family in 4,6){foreach($variant in $(if($historical){@('before','after')}else{@('after')})){
 $place=Join-Path $directory "ipv$family-$variant";New-Item -ItemType Directory -Path $place -Force|Out-Null
 $header=Join-Path $place 'coalesce-original.h';$source=if($variant-ceq'before'){Join-Path $before 'driver/v2/session_coalesce.h'}else{Join-Path $script:RepoRoot 'driver/v2/session_coalesce.h'};[IO.File]::WriteAllBytes($header,[IO.File]::ReadAllBytes($source))
 $lines=@();$bindings=[ordered]@{PB_BENCH_VERSION_SOURCE=(Join-Path $script:RepoRoot 'include/packetbridge_version.h');PB_BENCH_GUARD_SOURCE=(Join-Path $script:RepoRoot 'tests/safety/guard_memory.h');PB_BENCH_PROBE_SOURCE=(Join-Path $script:RepoRoot 'include/packetbridge_probe.h');PB_BENCH_STATE_SOURCE=(Join-Path $script:RepoRoot 'driver/v2/session_state.h');PB_COALESCE_SOURCE=$header}
 foreach($name in $bindings.Keys){$lines+='#define '+$name+' "'+$bindings[$name].Replace('\','/')+'"'};$lines+='#include "'+$test.Replace('\','/')+'"';$entry=Join-Path $place 'entry.c';[IO.File]::WriteAllText($entry,($lines-join"`n")+"`n",$utf8)
 $flags=@('/nologo','/std:c17','/MT','/O2','/W4','/WX','/DNDEBUG','/D_WIN32_WINNT=0x0601','/DNTDDI_VERSION=0x06010000',"/DPB_TEST_IP_VERSION=$family","/volatile:$Mode","/Fo$place\",'/FAs',"/Fa$place\")+@($script:VersionArguments|Where-Object {$_-notlike'/DPB_SOURCE_FINGERPRINT=*'})+"/DPB_SOURCE_FINGERPRINT=$script:SourceFingerprint"
 $exe=Join-Path $place 'coalesce-prefilter32.exe';$sources=@($entry,(Join-Path $script:RepoRoot 'common/v2_core.c'),(Join-Path $script:RepoRoot 'common/coalesce.c'),(Join-Path $script:RepoRoot 'common/packet.c'));$compile=Join-Path $place 'compile.log'
 & cl.exe @flags @sources /link "/out:$exe" *> $compile;if($LASTEXITCODE){throw "Coalesce benchmark compiler failed:$compile"}
 $builds+=@{ip_version=$family;variant=$variant;path=$exe;sha256=(Get-FileHash $exe).Hash.ToLowerInvariant();flags=$flags;entry=$entry;entry_sha256=(Get-FileHash $entry).Hash.ToLowerInvariant();source=$source;source_sha256=(Get-FileHash $source).Hash.ToLowerInvariant();header=$header;header_sha256=(Get-FileHash $header).Hash.ToLowerInvariant();compile_log=$compile;compile_log_sha256=(Get-FileHash $compile).Hash.ToLowerInvariant();assembly=@(Get-ChildItem -LiteralPath $place -Filter '*.asm'|ForEach-Object {@{path=$_.FullName;sha256=(Get-FileHash $_.FullName).Hash.ToLowerInvariant()}})}
}}
function Read-PrefilterSamples([string]$text,[int]$family){
 $records=@($text-split'\r?\n'|Where-Object {$_}|ForEach-Object {$_|ConvertFrom-Json});$rows=@($records|Where-Object {!$_.summary});$summary=@($records|Where-Object {$_.summary})
 if($rows.Count-ne30-or$summary.Count-ne1-or$records.Count-ne31){throw 'Coalesce benchmark sample count differs'}
 $shapes=@('eligible','wrong-mode','disabled-all','checksum-bad','flow4');$lengths=@(64,1500,65535)
 for($i=0;$i-lt30;++$i){$r=$rows[$i];$length=$lengths[[int][Math]::Floor(($i%15)/5)];$wanted=if($r.shape-ceq'eligible'-and$length-ne65535){1}elseif($r.shape-ceq'flow4'-and$length-ne65535){8}else{32};$iters=if($length-eq65535){[Math]::Max(1,[int][Math]::Floor($Iterations/16))}else{$Iterations}
 if($r.ip-ne$family-or$r.protocol-ne$(if($i-lt15){6}else{17})-or$r.length-ne$length-or$r.shape-cne$shapes[$i%5]-or$r.packets-ne32-or$r.iterations-lt$iters-or$r.warm-ne$Warmup-or$r.target_ms-ne$MinimumSampleMilliseconds-or$r.calibration_passes-lt1-or$r.calibration_ticks-lt0-or$r.groups-ne$wanted-or!$r.validated-or$r.source_hash-cnotmatch'^[a-f0-9]{16}$'-or$r.output_hash-cnotmatch'^[a-f0-9]{16}$'-or$r.qpc_ticks-lt0-or$r.qpc_frequency-le0-or$r.cycles-lt0-or$r.cpu_100ns-lt0-or$r.ns_per_batch-lt0-or$r.cycles_per_batch-lt0-or$r.cpu_ns_per_batch-lt0){throw "Coalesce benchmark row differs:$i"}}
 $s=$summary[0];if($s.ip-ne$family-or$s.cases-ne30-or$s.owned-ne0-or$s.handles_before-ne$s.handles_after-or$s.affinity-le0){throw 'Coalesce benchmark owner/affinity summary differs'}
 return @{rows=$rows;summary=$s}
}
$samples=@();$operations=@();foreach($family in 4,6){for($run=0;$run-lt$Runs;++$run){$order=if(!$historical){@('after')}elseif($run%2){@('after','before','before','after')}else{@('before','after','after','before')};$position=0;foreach($variant in $order){
 $build=@($builds|Where-Object {$_.ip_version-eq$family-and$_.variant-ceq$variant})[0];$info=[Diagnostics.ProcessStartInfo]::new($build.path);$info.ArgumentList.Add([string]$Iterations);$info.ArgumentList.Add([string]$Warmup);$info.ArgumentList.Add([string]$MinimumSampleMilliseconds);$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$p=[Diagnostics.Process]::new();$p.StartInfo=$info
 try{if(!$p.Start()){throw 'Cannot start coalesce benchmark'};$stdout=$p.StandardOutput.ReadToEndAsync();$stderr=$p.StandardError.ReadToEndAsync();if(!$p.WaitForExit(180000)){$p.Kill($true);$p.WaitForExit();throw 'Coalesce benchmark watchdog expired'};$text=$stdout.GetAwaiter().GetResult()+$stderr.GetAwaiter().GetResult();$log=Join-Path $directory "ipv$family-run$run-pos$position-$variant.log";[IO.File]::WriteAllText($log,$text,$utf8);if($p.ExitCode){throw "Coalesce benchmark process exit$($p.ExitCode):$log"};$read=Read-PrefilterSamples $text $family;$operations+=@{program=$build.path;arguments=@($Iterations,$Warmup,$MinimumSampleMilliseconds);ip_version=$family;variant=$variant;run=$run;position=$position;exit_code=$p.ExitCode;log=$log;log_sha256=(Get-FileHash $log).Hash.ToLowerInvariant();metrics=$read.summary};foreach($r in $read.rows){$samples+=@{run=$run;position=$position;variant=$variant;measurement=$r}}}finally{$p.Dispose()};++$position
}}}
function Median([object[]]$values){$v=@($values|Sort-Object);$at=[int][Math]::Floor($v.Count/2);if($v.Count%2){return $v[$at]};return ($v[$at-1]+$v[$at])/2}
$medians=@();foreach($family in 4,6){foreach($protocol in 6,17){foreach($length in 64,1500,65535){foreach($shape in 'eligible','wrong-mode','disabled-all','checksum-bad','flow4'){
 $group=@($samples|Where-Object {$_.measurement.ip-eq$family-and$_.measurement.protocol-eq$protocol-and$_.measurement.length-eq$length-and$_.measurement.shape-ceq$shape});$hashes=@($group|ForEach-Object {$_.measurement.source_hash+':'+$_.measurement.output_hash+':'+$_.measurement.groups}|Select-Object -Unique);if($hashes.Count-ne1){throw 'Coalesce benchmark before/after semantics differ'};$values=@{}
 foreach($variant in $(if($historical){@('before','after')}else{@('after')})){$rows=@($group|Where-Object variant -CEQ $variant);$expected=if($historical){$Runs*2}else{$Runs};if($rows.Count-ne$expected){throw 'Coalesce benchmark ABBA sample count differs'};$values[$variant]=@{samples=$rows.Count;ns_per_batch=Median @($rows|ForEach-Object {$_.measurement.ns_per_batch});cycles_per_batch=Median @($rows|ForEach-Object {$_.measurement.cycles_per_batch});cpu_ns_per_batch=Median @($rows|ForEach-Object {$_.measurement.cpu_ns_per_batch});ns_per_batch_min=($rows|ForEach-Object {$_.measurement.ns_per_batch}|Measure-Object -Minimum).Minimum;ns_per_batch_max=($rows|ForEach-Object {$_.measurement.ns_per_batch}|Measure-Object -Maximum).Maximum;cycles_per_batch_min=($rows|ForEach-Object {$_.measurement.cycles_per_batch}|Measure-Object -Minimum).Minimum;cycles_per_batch_max=($rows|ForEach-Object {$_.measurement.cycles_per_batch}|Measure-Object -Maximum).Maximum}}
 $medians+=@{ip_version=$family;protocol=$protocol;length=$length;shape=$shape;values=$values;ns_change_percent=$(if($historical-and$values.before.ns_per_batch){100*($values.after.ns_per_batch/$values.before.ns_per_batch-1)}else{$null})}
}}}}
foreach($dep in $dependencies){if((Get-FileHash (Join-Path $script:RepoRoot $dep.path)).Hash.ToLowerInvariant()-cne$dep.sha256-or(Get-FileHash $dep.snapshot).Hash.ToLowerInvariant()-cne$dep.sha256){throw 'Coalesce benchmark closure changed'}}
if((Get-SourceFingerprint)-cne$script:SourceFingerprint){throw 'Coalesce benchmark source changed'}
@{schema_version=1;version=$script:Version;source_tree_sha256=$script:SourceFingerprint;source_mode=$(if($historical){'explicit-historical-abba'}else{'current-source'});baseline_source_tree_sha256=$(if($historical){$accepted}else{$null});baseline=$before;dependencies=$dependencies;builds=$builds;runs=$Runs;iterations=$Iterations;warmup=$Warmup;minimum_sample_milliseconds=$MinimumSampleMilliseconds;run_status=$script:CoalesceBenchmarkStatus;operations=$operations;samples=$samples;medians=$medians;executed_processes=$operations.Count;kernel_runtime_tested=$false;production_ready=$false;performance_thresholds=@();
 method='Actual unchanged header body per before/current variant with shared current coalescer/packet/core. Independent family executables cover TCP/UDP32,64/1500/65535B and eligible/wrong-mode/disabled-all/checksum-bad/flow4. Before and after source bytes, valid complete output and independent header/checksum oracle are checked outside timing; source mapping read-only and guard allocations surround scratch/output. Large packets cannot merge to a65535B SCU and are explicitly validated as32 fallback groups. Timed loop is actual helper plus normal busy-owner return and a result sink; no packet comparisons, checksum oracle or logging in timing. QPC/thread-cycle/threadCPU raw deltas, fixed lowest eligible affinity, checked warmup and per-case doubling calibration toward at least the requested30ms-or-greater target; calibrated iterations are recorded independently in each raw sample. Final timing has no strict duration threshold because scheduling/frequency noise remains. Alternating ABBA/BAAB multi-round order; no jitter-sensitive thresholds. CPU100ns may have coarse zero values. Current-only is standalone and makes no A/B claim. Optional explicit accepted743-file baseline is full raw/typedOrdinal authenticated and all other driver/common/include/guard/version closure paths remain identical. Host kernel shims/native structs/DDIs are models, not actual NDIS/IRQL or native CPU/throughput/leak proof. Version2.0.0 unchanged.';
 audit_sources=@('tests/bench/coalesce_prefilter32_bench.c','tools/audit/bench-coalesce-prefilter32.ps1'|ForEach-Object {@{path=$_;sha256=(Get-FileHash (Join-Path $script:RepoRoot $_)).Hash.ToLowerInvariant()}})}|ConvertTo-Json -Depth 18|Set-Content -LiteralPath (Join-Path $directory 'evidence.json') -Encoding utf8
Write-CoalesceBenchmarkStatus -State 'passed' -EvidenceHash (Get-FileHash -LiteralPath (Join-Path $directory 'evidence.json')).Hash.ToLowerInvariant()
Write-Output (Join-Path $directory 'evidence.json')
